    newGalleryForm: { linksLabel: "Link", title: "Nuova galleria", subtitle: "Collega una cartella dal tuo Google Drive", subscriptionTitle: "Abbonamento richiesto", subscriptionSubtitle: "Ottieni accesso per creare gallerie illimitate", nameLabel: "Nome galleria", namePlaceholder: "es. Anna & George Wedding 2026", driveLabel: "Link cartella Google Drive", drivePlaceholder: "https://drive.google.com/drive/folders/...", driveHint: 'Assicurati che la cartella sia condivisa con "Chiunque abbia il link"', passwordLabel: "Password", passwordOptional: "(opzionale)", passwordPlaceholder: "Password galleria", create: "Crea galleria →", creating: "Creazione...", cancel: "Annulla", buy: "Acquista con carta →", backToForm: "Torna al modulo", perYear: "/ anno", offer: "Offerta", f1: "Gallerie illimitate", f2: "Foto e video illimitati", f3: "Password per galleria", f4: "Visualizzazione a schermo intero", f5: "Preferiti del cliente", f6: "Download in piena risoluzione", descriptionLabel: "Descrizione", descriptionPlaceholder: "Qualche parola su questa galleria...", eventDateLabel: "Data dell'evento", locationLabel: "Luogo", locationPlaceholder: "Città, Paese", error: "Qualcosa è andato storto" },
