    galleryCard: { linksLabel: "Enlaces", password: "Contraseña", selections: "Selección del cliente", selectionsTitle: "Favoritas del cliente", noSelections: "El cliente aún no ha seleccionado fotos.", noSelectionsHint: "Cuando toque el corazón en las fotos, aparecerán aquí.", photosSelected: "fotos seleccionadas", copyList: "Copiar lista", downloadFiles: "Descargar archivos (.zip)", preparing: "Preparando...", allowDownloadLabel: "Permitir descarga de fotos", allowDownloadHint: "Desactívalo si el cliente solo debe ver y elegir (p. ej. antes de pagar).", copyLink: "Copiar enlace", copied: "Copiado", openGallery: "Abrir galería", edit: "Editar", delete: "Eliminar", nameLabel: "Nombre", driveFolderLabel: "Carpeta de Google Drive", driveTooltip: "Para cambiar la carpeta, crea una nueva galería", newPasswordLabel: "Nueva contraseña (dejar en blanco para mantener la actual)", passwordOptionalLabel: "Contraseña (opcional)", noPassword: "Sin contraseña", removePassword: "Eliminar contraseña", save: "Guardar", cancel: "Cancelar", deleteTitle: "¿Eliminar galería?", deleteBody1: "La galería", deleteBody2: "será eliminada permanentemente. Las fotos en Drive no se tocarán.", chooseCover: "Elegir portada", coverModalTitle: "Selecciona una foto de portada", coverCurrent: "Portada actual", coverRemove: "Quitar portada", coverSaved: "Portada actualizada", bookCtaLabel: "Botón reservar fotógrafo", bookLinkPlaceholder: "mailto:you@email.com, https://wa.me/123, https://m.me/page", titleFontLabel: "Fuente del título", titleColorLabel: "Color del título", titleSizeLabel: "Tamaño del título", sizeSmall: "Pequeño", sizeMedium: "Medio", sizeLarge: "Grande", sizeXLarge: "Extra", fontClassic: "Clásica", fontSerif: "Elegante", fontScript: "Manuscrita", fontModern: "Moderna", fontMono: "Mono", descriptionLabel: "Descripción", eventDateLabel: "Fecha del evento", locationLabel: "Ubicación", error: "Algo salió mal." },
    faq: { title: "FAQ", subtitle: "¿Tienes una pregunta? La respuesta probablemente está aquí.", back: "← Volver", noAnswerTitle: "¿No encontraste tu respuesta?", noAnswerSubtitle: "Envíanos un correo y responderemos lo antes posible.", questions: [
      { q: "¿Necesito subir mis fotos a algún sitio?", a: "No. Tus fotos se quedan exactamente donde están, en tu Google Drive. PhotoDrive las lee desde allí y las muestra a tu cliente. No necesitas hacer nada de nuevo." },
      { q: "¿Cómo ve mi cliente la galería?", a: "Una vez que creas una galería, PhotoDrive genera automáticamente un enlace único. Se lo envías a tu cliente por correo o SMS. El cliente abre el enlace y ve la galería inmediatamente, sin registro, sin cuenta." },
      { q: "¿Puedo añadir contraseña a la galería?", a: "Sí. Al crear una galería puedes establecer una contraseña. Tu cliente deberá introducirla antes de ver las fotos. La contraseña se guarda encriptada." },
      { q: "¿Necesita mi cliente una cuenta de Google?", a: "No. Tu cliente no necesita ninguna cuenta. Simplemente abre el enlace que le enviaste y ve la galería. Si hay contraseña, solo necesita introducirla." },
      { q: "¿Puede mi cliente descargar las fotos?", a: "Sí. El cliente puede descargar fotos individuales en resolución completa o varias fotos como archivo ZIP." },
      { q: "¿Qué pasa si añado o elimino fotos de Google Drive?", a: "La galería se actualiza automáticamente. Las fotos que añadas aparecerán en la galería, las que elimines desaparecerán. No necesitas hacer nada en PhotoDrive." },
      { q: "¿Cuántas galerías puedo crear?", a: "Ilimitadas. Tu suscripción no tiene límite en el número de galerías o fotos." },
      { q: "¿Qué tipos de archivos se admiten?", a: "PhotoDrive admite todos los formatos de imagen comunes (JPEG, PNG, WebP, HEIC, etc.) así como vídeos (MP4, MOV, etc.)." },
      { q: "¿Están seguras mis fotos?", a: "PhotoDrive tiene acceso de solo lectura a la carpeta de Drive que eliges. No guardamos tus fotos en ningún lugar. No modificamos ni eliminamos nada en tu Drive." },
      { q: "¿Qué pasa si la carpeta de Drive no es pública?", a: 'La carpeta de Drive debe estar configurada para que "Cualquier persona con el enlace" pueda verla. Esto no significa que tu carpeta aparezca en Google.' },
      { q: "¿En qué dispositivos funciona PhotoDrive?", a: "PhotoDrive funciona en cualquier navegador moderno, Chrome, Safari, Firefox, Edge, en escritorio, tablet y móvil." },
    ]},
