export type Translations = typeof translations.el;

const LanguageContext = createContext<{
  lang: Lang;
  t: Translations;
  toggle: () => void;
  setLanguage: (l: Lang) => void;
}>({
  lang: "en",
  t: translations.en as unknown as Translations,
  toggle: () => {},
  setLanguage: () => {},
});

const TITLES: Record<Lang, string> = {
  el: "PhotoDrive, Επαγγελματικά galleries για φωτογράφους",
  en: "PhotoDrive, Professional galleries for photographers",
  nl: "PhotoDrive, Professionele galerijen voor fotografen",
  de: "PhotoDrive, Professionelle Galerien für Fotografen",
  es: "PhotoDrive, Galerías profesionales para fotógrafos",
  it: "PhotoDrive, Gallerie professionali per fotografi",
};

// Pick the best supported language from the browser's preferences.
// Falls back to English if none of the browser languages are supported.
function detectBrowserLang(): Lang {
  if (typeof navigator === "undefined") return "en";
  const prefs = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const tag of prefs) {
    const code = tag.toLowerCase().split("-")[0] as Lang;
    if (code in TITLES) return code;
  }
  return "en";
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLang] = useState<Lang>("en");

  useEffect(() => {
    const saved = localStorage.getItem("lang") as Lang;
    if (saved && saved in TITLES) {
      setLang(saved);
      document.title = TITLES[saved];
      return;
    }
    // No saved preference: auto-pick from the browser language.
    // English stays the default; Greek (or any other supported locale) is
    // used when that's what the visitor's browser is set to.
    const detected = detectBrowserLang();
    if (detected !== "en") {
      setLang(detected);
      document.title = TITLES[detected];
    }
  }, []);

  // Keep <html lang> in sync with the active language so the browser applies
  // language-correct casing, notably, Greek removes accents on uppercase
  // (text-transform: uppercase), e.g. "Πώς" → "ΠΩΣ" instead of "ΠΏΣ".
  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);

  function applyLang(next: Lang) {
    localStorage.setItem("lang", next);
    document.title = TITLES[next];
    setLang(next);
  }

  function toggle() {
    const order = Object.keys(TITLES) as Lang[];
    setLang((prev) => {
      const next = order[(order.indexOf(prev) + 1) % order.length];
      localStorage.setItem("lang", next);
      document.title = TITLES[next];
      return next;
    });
  }

  return (
    <LanguageContext.Provider value={{ lang, t: translations[lang] as unknown as Translations, toggle, setLanguage: applyLang }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  return useContext(LanguageContext);
}
